import unittest
from src.billcalc import compute_total


class TestBillcalc(unittest.TestCase):
    def test_simple_total(self):
        items = [{"price": 10.0, "qty": 2}]
        self.assertEqual(compute_total(items, 0.1), 22.0)


if __name__ == "__main__":
    unittest.main()
